import { useState } from 'react';
import styles from './TransactionForm.module.css';

const TransactionForm = ({ onAddTransaction }) => {
  const [formData, setFormData] = useState({
    description: '',
    amount: '',
    type: 'income', // Por defecto es 'income'
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    // Obtener la fecha y hora actual
    const now = new Date();
    const dayOfWeek = now.toLocaleDateString('es-ES', { weekday: 'long' }); // Día de la semana (ej: "lunes")
    const time = now.toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' }); // Hora (ej: "14:30")

    const transaction = {
      ...formData,
      amount: parseFloat(formData.amount), // Convertir a número
      day: dayOfWeek, // Día de la semana
      time: time, // Hora de la transacción
    };

    onAddTransaction(transaction); // Enviar la transacción al Dashboard
    setFormData({
      description: '',
      amount: '',
      type: 'income',
    });
  };

  return (
    <form className={styles.form} onSubmit={handleSubmit}>
      <input
        type="text"
        name="description"
        placeholder="Descripción"
        value={formData.description}
        onChange={handleChange}
        required
      />
      <input
        type="number"
        name="amount"
        placeholder="Monto"
        value={formData.amount}
        onChange={handleChange}
        required
      />
      <select name="type" value={formData.type} onChange={handleChange}>
        <option value="income">Ingreso</option>
        <option value="expense">Gasto</option>
      </select>
      <button type="submit">Agregar Transacción</button>
    </form>
  );
};

export default TransactionForm;
